package locksvc

import (
	"sync"
	"time"
)

// Service is the queryable, in-process lock-state service.
//
// Every method holds mu so all operations — including the deterministic transfer
// of expired leases — are serialized. Expired leases are swept at the start of
// every acquire, release, renew and query so consecutive and concurrent calls see
// the same effective state.
type Service struct {
	mu    sync.Mutex
	now   func() time.Time
	locks map[string]*entry
	// held indexes ownerID -> resourceID for owners with an active holding. It is
	// kept in sync with entries and rebuilt defensively if a transfer collision is
	// ever observed.
	held map[string]string
}

// Option customizes a Service.
type Option func(*Service)

// WithClock overrides the time source. It is intended for deterministic tests.
func WithClock(clock func() time.Time) Option {
	return func(s *Service) {
		if clock != nil {
			s.now = clock
		}
	}
}

// New creates an empty lock-state service.
func New(opts ...Option) *Service {
	s := &Service{
		now:   time.Now,
		locks: make(map[string]*entry),
		held:  make(map[string]string),
	}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// SetClock replaces the time source after construction (tests only).
func (s *Service) SetClock(clock func() time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if clock != nil {
		s.now = clock
	}
}

// setHeld updates the owner -> resource index. A system-driven transfer is
// unconditional, so the most recent winning resource wins the index.
func (s *Service) setHeld(ownerID, resourceID string) {
	if ownerID == "" {
		return
	}
	s.held[ownerID] = resourceID
}

func (s *Service) clearHeld(ownerID, resourceID string) {
	if existing, ok := s.held[ownerID]; ok && existing == resourceID {
		delete(s.held, ownerID)
	}
}

// sweepLocked transfers every expired lease. With waiters the head waiter becomes
// the holder with a fresh lease measured from now; without waiters the resource
// becomes free and keeps a former-owner marker. The caller holds mu.
func (s *Service) sweepLocked(now time.Time) {
	for resourceID, e := range s.locks {
		if !e.locked() || !e.expired(now) {
			continue
		}
		oldOwner := e.ownerID
		if len(e.waiting) > 0 {
			head := e.waiting[0]
			e.waiting = e.waiting[1:]
			e.ownerID = head.OwnerID
			e.leaseSeconds = head.RequestedLeaseSeconds
			e.leaseExpiresAt = now.Add(time.Duration(head.RequestedLeaseSeconds) * time.Second)
			e.reentryCount = 1
			e.formerOwner = oldOwner
			s.setHeld(head.OwnerID, resourceID)
		} else {
			e.ownerID = ""
			e.leaseExpiresAt = time.Time{}
			e.leaseSeconds = 0
			e.reentryCount = 0
			e.formerOwner = oldOwner
		}
		s.clearHeld(oldOwner, resourceID)
	}
}

// snapshotLocked copies one record into the public view. The caller holds mu.
func (s *Service) snapshotLocked(resourceID string, e *entry) ResourceState {
	state := ResourceState{
		ResourceID: resourceID,
		Exists:     e != nil,
		Waiting:    []Waiter{},
	}
	if e == nil {
		return state
	}
	state.Locked = e.locked()
	state.OwnerID = e.ownerID
	state.LeaseExpiresAt = e.leaseExpiresAt
	state.ReentryCount = e.reentryCount
	if len(e.waiting) > 0 {
		state.Waiting = append(state.Waiting, e.waiting...)
	}
	return state
}
package locksvc

import "time"

// Outcome status values. ACQUIRED/REENTRY/WAITING/RELEASED/REENTRY_DECREMENTED keep
// the semantics of the existing resource-lock entry points; RENEWED is returned by
// Renew.
const (
	StatusAcquired         = "ACQUIRED"
	StatusReentry          = "REENTRY"
	StatusWaiting          = "WAITING"
	StatusReleased         = "RELEASED"
	StatusReentryDecrement = "REENTRY_DECREMENTED"
	StatusRenewed          = "RENEWED"
)

// Waiter is one queued request, in enqueue order.
type Waiter struct {
	OwnerID               string `json:"ownerId"`
	RequestedLeaseSeconds int64  `json:"requestedLeaseSeconds"`
}

// ResourceState is the full, current view of one resource.
//
// Exists is false for a resource that has never appeared. After a lease expires
// with no waiters the record stays around as a former-owner marker and Exists is
// still true while Locked is false; after a voluntary release with an empty queue
// the record is removed. When Locked is false, OwnerID is empty, LeaseExpiresAt is
// the zero time and ReentryCount is 0.
type ResourceState struct {
	ResourceID     string    `json:"resourceId"`
	Exists         bool      `json:"exists"`
	Locked         bool      `json:"locked"`
	OwnerID        string    `json:"ownerId"`
	LeaseExpiresAt time.Time `json:"leaseExpiresAt"`
	ReentryCount   int64     `json:"reentryCount"`
	Waiting        []Waiter  `json:"waitingOwners"`
}

// HeldResource is one resource currently held by a queried owner.
type HeldResource struct {
	ResourceID     string    `json:"resourceId"`
	LeaseSeconds   int64     `json:"leaseSeconds"`
	LeaseExpiresAt time.Time `json:"leaseExpiresAt"`
	ReentryCount   int64     `json:"reentryCount"`
}

// HolderState answers an owner query.
type HolderState struct {
	OwnerID string         `json:"ownerId"`
	Holds   []HeldResource `json:"holds"`
}

// Outcome is the result of a state-changing operation.
type Outcome struct {
	Status string
	State  ResourceState
}

// entry is the mutable record of one resource.
type entry struct {
	ownerID        string
	leaseExpiresAt time.Time
	leaseSeconds   int64
	reentryCount   int64
	waiting        []Waiter
	// formerOwner remembers the holder whose lease expired so its late release or
	// renewal keeps returning ErrLeaseExpired. It is cleared when that owner starts
	// a fresh holding or enqueues on the resource again.
	formerOwner string
}

func (e *entry) locked() bool { return e.ownerID != "" }

func (e *entry) expired(now time.Time) bool {
	return e.ownerID != "" && !now.Before(e.leaseExpiresAt)
}
// Package locksvc is an in-process, queryable lock-state service.
//
// It records one record per resource: the current holder, the lease expiry, the
// reentry count, and the waiting queue. All state lives in memory for the lifetime
// of the process; no persistence files are written and losing state on shutdown is
// not an error. Identifiers are used exactly as supplied, without case folding or
// truncation.
package locksvc

import "errors"

// Sentinel errors carry the names required by the service contract. The canonical
// names use the Error suffix; Err-prefixed aliases match the existing store layer.
var (
	ErrInvalidLeaseDuration  = errors.New("invalid lease duration")
	ErrInvalidReentryCount   = errors.New("invalid reentry count")
	ErrInvalidLockIdentity   = errors.New("invalid lock identity")
	ErrInvalidHolderIdentity = errors.New("invalid holder identity")
	ErrNotLockOwner          = errors.New("not lock owner")
	ErrLeaseExpired          = errors.New("lease expired")
	ErrDuplicateWaiter       = errors.New("duplicate waiter")
	ErrDuplicateHold         = errors.New("duplicate hold")

	InvalidLeaseDurationError  = ErrInvalidLeaseDuration
	InvalidReentryCountError   = ErrInvalidReentryCount
	InvalidLockIdentityError   = ErrInvalidLockIdentity
	InvalidHolderIdentityError = ErrInvalidHolderIdentity
	NotLockOwnerError          = ErrNotLockOwner
	LeaseExpiredError          = ErrLeaseExpired
	DuplicateWaiterError       = ErrDuplicateWaiter
	DuplicateHoldError         = ErrDuplicateHold
)

