}

func renderLockState(state locksvc.ResourceState) lockStateView {
	view := lockStateView{
		ResourceID:    state.ResourceID,
		Exists:        state.Exists,
		Locked:        state.Locked,
		ReentryCount:  state.ReentryCount,
		WaitingOwners: []waitingOwnerView{},
	}
	if state.OwnerID != "" {
