package store

import (
	"database/sql"
	"errors"
)

// CancelWaiting withdraws one pending waiting request. The current holder, the
// lease, and the reentry count are left untouched, and the remaining waiters
// keep their entry order and requested lease seconds. A caller that is not a
// pending waiter — including the current holder or an owner already promoted by
// a lease transfer — is rejected with ErrNotWaiting and nothing changes.
func (s *Store) CancelWaiting(resourceID, ownerID string) (Outcome, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return Outcome{}, err
	}
	defer tx.Rollback()

	if _, err := readRow(tx, resourceID); errors.Is(err, sql.ErrNoRows) {
		return Outcome{}, ErrResourceNotFound
	} else if err != nil {
		return Outcome{}, err
	}

	waiting, err := isWaiting(tx, resourceID, ownerID)
	if err != nil {
		return Outcome{}, err
	}
	if !waiting {
		return Outcome{}, ErrNotWaiting
	}

	if _, err := tx.Exec(
		`DELETE FROM waiting_requests WHERE resource_id = ? AND owner_id = ?`,
		resourceID, ownerID,
	); err != nil {
		return Outcome{}, err
	}
	if err := tx.Commit(); err != nil {
		return Outcome{}, err
	}
	state, err := s.getStateLocked(resourceID)
	if err != nil {
		return Outcome{}, err
	}
	return Outcome{Status: StatusCanceled, State: state}, nil
}
package store

import (
	"database/sql"
	"errors"
	"time"
)

// GetState reads one resource without changing the holder, lease, or queue.
// A resource that has never been seen returns ErrResourceNotFound; a known but
// holderless resource returns empty owner fields, a zero reentry count, and an
// empty waiting queue.
func (s *Store) GetState(resourceID string) (State, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.getStateLocked(resourceID)
}

// getStateLocked assumes the caller already holds mu.
func (s *Store) getStateLocked(resourceID string) (State, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return State{}, err
	}
	defer tx.Rollback()

	var state State
	state.ResourceID = resourceID
	state.WaitingOwners = []WaitingOwner{}

	var ownerID sql.NullString
	var leaseExpiresAt sql.NullInt64
	err = tx.QueryRow(
		`SELECT owner_id, lease_expires_at FROM resources WHERE resource_id = ?`,
		resourceID,
	).Scan(&ownerID, &leaseExpiresAt)
	if errors.Is(err, sql.ErrNoRows) {
		return State{}, ErrResourceNotFound
	}
	if err != nil {
		return State{}, err
	}
	if ownerID.Valid {
		state.OwnerID = ownerID.String
	}
	if leaseExpiresAt.Valid {
		state.LeaseExpiresAt = time.UnixMilli(leaseExpiresAt.Int64).UTC()
	}
	if err := tx.QueryRow(
		`SELECT reentry_count FROM resources WHERE resource_id = ?`, resourceID,
	).Scan(&state.ReentryCount); err != nil {
		return State{}, err
	}

	rows, err := tx.Query(
		`SELECT owner_id, lease_seconds FROM waiting_requests
		 WHERE resource_id = ? ORDER BY id`, resourceID,
	)
	if err != nil {
		return State{}, err
	}
	defer rows.Close()
	for rows.Next() {
		var waiting WaitingOwner
		if err := rows.Scan(&waiting.OwnerID, &waiting.RequestedLeaseSecond); err != nil {
			return State{}, err
		}
		state.WaitingOwners = append(state.WaitingOwners, waiting)
	}
	return state, rows.Err()
}

